    val script = "if (window.vtuberApi) { window.vtuberApi.$method($args); }"
    if (ready) {
        webView.evaluateJavascript(script, null)
    } else {
        queued.add(script)
    }
}

private fun quote(text: String): String {
    val escaped = text
        .replace("\\", "\\\\")
        .replace("'", "\\'")
        .replace("\n", " ")
        .replace("\r", " ")
    return "'$escaped'"
}

